-- Executed by FR-30-push.py after the existing rollback-only FR30 SQL fixtures.
-- All identities, registrations, broadcasts and jobs are synthetic and rolled back.
update fr30_private.limits set android_push_enabled=false;
select pg_temp.claim('customer');
select pg_temp.ok(public.fr30_register_push('00000000-0000-0000-0000-000000000030','synthetic-installation',repeat('a',64))->>'code'='PUSH_NOT_CONFIGURED','disabled registration');
update fr30_private.limits set android_push_enabled=true,cooldown_seconds=0;
create temp table fr30_push_context(installation uuid,broadcast uuid,job uuid,lease uuid);
insert into fr30_push_context values('00000000-0000-0000-0000-000000000030',gen_random_uuid(),null,null);
select pg_temp.ok(public.fr30_register_push((select installation from fr30_push_context),'synthetic-installation',repeat('a',64))->>'code'='REGISTERED','authenticated device registration');
select pg_temp.ok(public.fr30_register_push(gen_random_uuid(),'bad',repeat('a',64))->>'code'='INVALID_INPUT','invalid registration');
select pg_temp.ok((select secret_hash<>repeat('a',64)and token_hash<>token from fr30_private.push_devices where id=(select installation from fr30_push_context)),'server stores capability hash');
select pg_temp.claim('blocked');
select pg_temp.ok(public.fr30_register_push(gen_random_uuid(),'blocked-installation',repeat('b',64))->>'code'='FORBIDDEN','blocked registration denied');
select pg_temp.claim('admin');
select pg_temp.ok(public.admin_send_broadcast((select broadcast from fr30_push_context),'Synthetic private push','Plain <b>text</b>','CUSTOMERS')->>'code'='SENT','in-app accepted with transactional outbox');
select pg_temp.ok((select count(*)=1 from fr30_private.push_deliveries where device_id=(select installation from fr30_push_context)),'exactly one installation snapshot job');
select pg_temp.ok((select count(*)=1 from public.security_audit_log where broadcast_id=(select broadcast from fr30_push_context)),'push adds no duplicate audit');
select pg_temp.claim('customer');
select pg_temp.ok(public.fr30_register_push(gen_random_uuid(),'synthetic-late-installation',repeat('b',64))->>'code'='REGISTERED','later device registration');
select pg_temp.ok((select count(*)=1 from fr30_private.push_deliveries where user_id=(select id from fr30_people where label='customer')and notification_id in(select id from public.notifications where broadcast_id=(select broadcast from fr30_push_context))),'late registration does not gain old jobs');
select pg_temp.ok(not has_function_privilege('authenticated','public.fr30_claim_push(integer)','EXECUTE'),'client cannot claim');
select pg_temp.ok(not has_function_privilege('anon','public.fr30_finish_push(uuid,uuid,text,text)','EXECUTE'),'anonymous cannot finish');
select pg_temp.ok(not has_function_privilege('authenticated','public.fr30_push_eligible(uuid,uuid)','EXECUTE'),'client cannot inspect jobs');
select pg_temp.ok(not has_table_privilege('authenticated','fr30_private.push_devices','SELECT'),'client cannot enumerate devices');
select pg_temp.ok(not has_table_privilege('anon','fr30_private.push_deliveries','SELECT'),'anonymous cannot enumerate jobs');
select pg_temp.ok(public.fr30_resolve_push((select installation from fr30_push_context),repeat('f',64),(select broadcast from fr30_push_context))->>'code'='FORBIDDEN','wrong device capability denied');
select pg_temp.ok(public.fr30_resolve_push((select installation from fr30_push_context),repeat('a',64),gen_random_uuid())->>'code'='FORBIDDEN','wrong snapshot denied');
set local role anon;
do $$begin
 perform pg_temp.ok(public.fr30_resolve_push('00000000-0000-0000-0000-000000000030',null,gen_random_uuid())->>'code'='FORBIDDEN','anonymous without capability denied');
end$$;
reset role;
grant select on fr30_push_context to anon;
set local role anon;
select pg_temp.ok(public.fr30_resolve_push((select installation from fr30_push_context),repeat('a',64),(select broadcast from fr30_push_context))->>'code'='OK','anonymous transport requires valid scoped device capability');
reset role;
select pg_temp.ok(public.fr30_resolve_push((select installation from fr30_push_context),repeat('a',64),(select broadcast from fr30_push_context))->>'code'='OK','valid scoped capability resolves snapshot');
select set_config('request.jwt.claims','{"role":"service_role"}',true);
update fr30_push_context c set (job,lease)=(select (j->>'job_id')::uuid,(j->>'lease')::uuid from public.fr30_claim_push(50)j where exists(select 1 from fr30_private.push_deliveries d where d.id=(j->>'job_id')::uuid and d.device_id=c.installation)limit 1);
select pg_temp.ok((select job is not null and lease is not null from fr30_push_context),'worker claims live job');
select pg_temp.ok(public.fr30_push_eligible((select job from fr30_push_context),(select lease from fr30_push_context)),'eligible immediately before provider');
select pg_temp.ok((select count(*)=0 from public.fr30_claim_push(50)),'active lease not claimed twice');
select pg_temp.ok(public.fr30_finish_push((select job from fr30_push_context),gen_random_uuid(),'ACCEPTED')->>'code'='STALE_LEASE','wrong lease cannot finish');
select pg_temp.ok(public.fr30_finish_push((select job from fr30_push_context),(select lease from fr30_push_context),'RETRY')->>'code'='RECORDED','transient outcome persisted');
select pg_temp.ok((select state='RETRY'and due_at>clock_timestamp()and attempts=1 from fr30_private.push_deliveries where id=(select job from fr30_push_context)),'retry bounded and delayed');
update fr30_private.push_deliveries set due_at=clock_timestamp()-interval '1 second'where id=(select job from fr30_push_context);
update fr30_push_context c set lease=(select (j->>'lease')::uuid from public.fr30_claim_push(50)j limit 1);
select pg_temp.ok(public.fr30_finish_push((select job from fr30_push_context),(select lease from fr30_push_context),'ACCEPTED','projects/tez-rider/messages/synthetic')->>'code'='RECORDED','provider acceptance recorded');
select pg_temp.ok((select state='PROVIDER_ACCEPTED'from fr30_private.push_deliveries where id=(select job from fr30_push_context)),'provider acceptance distinct from device receipt');
update public.notifications set is_read=true where broadcast_id=(select broadcast from fr30_push_context);
select pg_temp.ok(public.fr30_resolve_push((select installation from fr30_push_context),repeat('a',64),(select broadcast from fr30_push_context))->>'code'='FORBIDDEN','already read notice not rendered');
update public.notifications set is_read=false where broadcast_id=(select broadcast from fr30_push_context);
update fr30_private.push_deliveries set expires_at=clock_timestamp()-interval '1 second'where id=(select job from fr30_push_context);
select pg_temp.ok(public.fr30_resolve_push((select installation from fr30_push_context),repeat('a',64),(select broadcast from fr30_push_context))->>'code'='FORBIDDEN','expired capability lookup denied');
update fr30_private.push_deliveries set expires_at=clock_timestamp()+interval '1 hour'where id=(select job from fr30_push_context);
select pg_temp.claim('vendor');
select pg_temp.ok(public.fr30_unregister_push((select installation from fr30_push_context))->>'code'='UNREGISTERED','other owner unregister is harmless');
select pg_temp.ok((select count(*)=1 from fr30_private.push_devices where id=(select installation from fr30_push_context)),'other owner cannot unregister device');
select pg_temp.ok(public.fr30_register_push((select installation from fr30_push_context),'synthetic-installation',repeat('c',64))->>'code'='REGISTERED','new authenticated owner rebinds device');
select pg_temp.ok(public.fr30_resolve_push((select installation from fr30_push_context),repeat('a',64),(select broadcast from fr30_push_context))->>'code'='FORBIDDEN','old owner capability invalidated');
select pg_temp.ok(public.fr30_resolve_push((select installation from fr30_push_context),repeat('c',64),(select broadcast from fr30_push_context))->>'code'='FORBIDDEN','new owner cannot resolve old owner snapshot');
select pg_temp.claim('customer');
select pg_temp.ok(public.fr30_register_push((select installation from fr30_push_context),'synthetic-installation',repeat('a',64))->>'code'='REGISTERED','restore synthetic installation');
select set_config('request.jwt.claims','{"role":"service_role"}',true);
update auth.sessions set not_after=clock_timestamp()-interval '1 second'where id=(select session_id from fr30_people where label='customer');
select pg_temp.ok(public.fr30_resolve_push((select installation from fr30_push_context),repeat('a',64),(select broadcast from fr30_push_context))->>'code'='FORBIDDEN','expired Auth session denied');
update auth.sessions set not_after=null where id=(select session_id from fr30_people where label='customer');
-- Retry exhaustion and invalid installations never produce success.
update fr30_private.push_deliveries set state='RETRY',attempts=4,due_at=clock_timestamp()-interval '1 second'where id=(select job from fr30_push_context);
update fr30_push_context c set lease=(select (j->>'lease')::uuid from public.fr30_claim_push(50)j limit 1);
select pg_temp.ok(public.fr30_finish_push((select job from fr30_push_context),(select lease from fr30_push_context),'RETRY')->>'code'='RECORDED','final transient result recorded');
select pg_temp.ok((select state='FAILED'and attempts=5 from fr30_private.push_deliveries where id=(select job from fr30_push_context)),'five attempts exhausted');
update fr30_private.push_deliveries set state='RETRY',attempts=0,due_at=clock_timestamp()-interval '1 second'where id=(select job from fr30_push_context);
update fr30_push_context c set lease=(select (j->>'lease')::uuid from public.fr30_claim_push(50)j limit 1);
select pg_temp.ok(public.fr30_finish_push((select job from fr30_push_context),(select lease from fr30_push_context),'INVALID_TOKEN')->>'code'='RECORDED','provider invalid installation recorded');
select pg_temp.ok(not exists(select 1 from fr30_private.push_devices where id=(select installation from fr30_push_context)),'provider invalid installation removed');
select pg_temp.claim('customer');
select pg_temp.ok(public.fr30_register_push((select installation from fr30_push_context),'synthetic-installation',repeat('a',64))->>'code'='REGISTERED','new registration after invalid installation');
select set_config('request.jwt.claims','{"role":"service_role"}',true);
update public.users set is_blocked=true where id=(select id from fr30_people where label='customer');
select pg_temp.ok(not exists(select 1 from fr30_private.push_devices where user_id=(select id from fr30_people where label='customer')),'blocking removes all owner registrations');
select pg_temp.ok(public.fr30_resolve_push((select installation from fr30_push_context),repeat('a',64),(select broadcast from fr30_push_context))->>'code'='FORBIDDEN','blocked owner lookup denied');
select pg_temp.ok((select count(*)=1 from cron.job where jobname='fr30-android-push'),'one durable retry scheduler');
select jsonb_agg(jsonb_build_object('check',name,'result',result))as results from fr30_results;
rollback;
